def can_finish(n, prereqs):
    g = [[] for _ in range(n)]; indeg = [0] * n
    for a, b in prereqs: g[b].append(a); indeg[a] += 1
    q = [i for i in range(n) if indeg[i] == 0]; done = 0
    while q:
        u = q.pop(); done += 1
        for v in g[u]:
            indeg[v] -= 1
            if indeg[v] == 0: q.append(v)
    return done == n

