bool canFinish(int n, vector<vector<int>>& pr) {
    vector<vector<int>> g(n); vector<int> indeg(n, 0);
    for (auto& e : pr) { g[e[1]].push_back(e[0]); indeg[e[0]]++; }
    vector<int> st; for (int i = 0; i < n; i++) if (!indeg[i]) st.push_back(i);
    int done = 0; while (!st.empty()) { int u = st.back(); st.pop_back(); done++; for (int v : g[u]) if (--indeg[v] == 0) st.push_back(v); }
    return done == n;
}
